# lab-run state machine (template generated by ai-lab).
#
# - LR-01: models per role (hcore/models.py, MD-07): --models holds for the
#   cycle only, "inherit" -> the Agent parameter is not passed.
# - LR-02: entry on a path under experiments/ whose status line is exactly
#   the ready status line of the protocol -> Build phase; otherwise Cadrage. The option
#   --models is taken out of $ARGUMENTS first. (The status lines are part of
#   the French protocol format and are kept as is.)
# - LR-03: an expert (neuro, math) that died or returned nothing usable is
#   relaunched once; the second time the cycle goes on and the decision
#   carries "expertise <neuro|math> not collected" (C2: also in the
#   interpretation phase).
# - LR-05: success if and only if verdict == APPROVED and tests_passed,
#   protocol_followed and rerun_consistent are all true; 3 iterations, then
#   explicit failure with an "experiment invalidated" journal entry.
# - LR-06: Builder or Verifier dead -> one relaunch without consuming an
#   iteration, then failure (C2).
# - LR-07: the cross interpretation runs once, after the Verifier approved.
# - LR-09: the lab Verifier schema is parsed by hcore/verdicts.py.

from __future__ import annotations

from pathlib import Path
from typing import Any, Dict, Optional, Tuple

from . import counters, profiles, relaunch, verdicts

# PX-04: the agents, their model roles and the ready status line come from the profile with a lab loop.
_PROFILE = profiles.by_machine("lab")
_AGENTS = profiles.loop_agents(_PROFILE)
_MODEL_ROLES = {r["name"]: r["model_role"] for r in _PROFILE["roles"]}
DIRECTOR = _AGENTS["plan"]
NEURO, MATH = _AGENTS["consult"]
BUILDER, VERIFIER = _AGENTS["build"], _AGENTS["verify"]
AGENTS = (DIRECTOR, NEURO, MATH, BUILDER, VERIFIER)
EXPERTS = {a: _MODEL_ROLES[a].rsplit(".", 1)[-1] for a in (NEURO, MATH)}
PRE_REGISTERED_LINE = profiles.ready_status(_PROFILE)
PRE_REGISTERED_LINES = tuple(profiles.ready_status_lines(_PROFILE))
MODES = ("cadrage", "interpretation")


class RunOver(RuntimeError):
    """Call after the end of the cycle (success or failure already returned)."""


def role_of(agent: str, mode: Optional[str]) -> str:
    """Model role of an agent call (MD-01)."""
    if agent == DIRECTOR:
        return _MODEL_ROLES[agent].rsplit(".", 1)[0] + "." + (mode or "cadrage")
    return _MODEL_ROLES[agent]


def entry(arguments: str, root: Path) -> Dict[str, Any]:
    """LR-02: picks the entry phase from $ARGUMENTS (without --models)."""
    candidate = (arguments or "").strip().strip("'\"")
    if candidate:
        try:
            path = Path(candidate)
            full = path if path.is_absolute() else Path(root) / path
            rel = full.resolve().relative_to(Path(root).resolve())
            is_protocol = full.is_file() and rel.parts[:1] == ("experiments",)
        except (OSError, ValueError):
            is_protocol = False
        if is_protocol:
            for line in full.read_text(encoding="utf-8", errors="replace").splitlines():
                if line.strip().lower().startswith(("status", "statut")):
                    if line.strip() in PRE_REGISTERED_LINES:
                        return {"mode": "build", "protocol": rel.as_posix()}
                    break
    return {"mode": "cadrage", "protocol": None}


def new_state(models: Optional[Dict[str, str]] = None, mode: str = "cadrage") -> Dict[str, Any]:
    return {
        "models": dict(models or {}),
        "iteration": 1,
        "max_iterations": counters.MAX_ITERATIONS,
        "failures": {},
        "status": "running",
        "issues": [],
        "phase": "build" if mode == "build" else "cadrage",
        "uncollected": [],
        "interpreted": False,
    }


def _dead(state: Dict[str, Any], key: str, reason: str, agent: str, iteration: int,
          expert: bool) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    log = {"iteration": iteration, "verdict": "DEAD", "produced": 0}
    failures = state["failures"].get(key, 0)
    state["failures"][key] = failures + 1
    if relaunch.on_dead(failures) == relaunch.RELAUNCH:
        return {"action": "relaunch", "agent": agent, "iteration": iteration, "reason": reason}, log
    if expert:
        name = EXPERTS[agent]
        if name not in state["uncollected"]:
            state["uncollected"].append(name)
        return {"action": "continue", "agent": agent, "iteration": iteration, "uncollected": list(state["uncollected"]),
                "note": "expertise %s not collected" % name}, log
    state["status"] = "failed"
    return {"action": "fail", "agent": agent, "iteration": iteration, "issues": state["issues"],
            "reason": "%s died twice (%s): explicit failure, no verdict" % (agent, reason)}, log


def record(state: Dict[str, Any], agent: str, mode: Optional[str], output: Optional[str],
           dead: bool) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """Applies an agent's return. Returns (decision, journal fields)."""
    if state["status"] != "running":
        raise RunOver("cycle already finished: %s" % state["status"])
    if agent not in AGENTS:
        raise ValueError("unknown agent: %r" % (agent,))
    if agent == DIRECTOR and mode not in MODES:
        raise ValueError("the Director needs --mode cadrage|interpretation")
    phase = state["phase"]
    iteration = state["iteration"] if agent in (BUILDER, VERIFIER) else 0
    key = agent + (":" + mode if agent == DIRECTOR else ":" + phase if agent in EXPERTS else "")
    reason = "dead agent" if dead else None
    parsed = None
    if agent == VERIFIER:
        if phase != "verify":
            raise ValueError("out-of-sequence call: the Verifier follows the Builder")
        if not dead:
            try:
                parsed = verdicts.parse_lab_verifier(output)
            except verdicts.UnusableOutput as exc:
                dead, reason = True, "unusable output: %s" % exc
    elif agent == BUILDER and phase == "cadrage":
        # Interactive cycle: the protocol is pre-registered (human gate) right after the
        # Director's framing, then the Builder starts the Build phase.
        if (DIRECTOR + ":cadrage") not in state["failures"]:
            raise ValueError("out-of-sequence call: the Director frames before the Builder")
        state["phase"] = phase = "build"
    elif agent == BUILDER and phase != "build":
        raise ValueError("out-of-sequence call: the Builder runs in the Build phase")
    elif agent in EXPERTS and phase not in ("cadrage", "interpret"):
        raise ValueError("the experts run in the Cadrage and Interpretation phases")
    elif agent == DIRECTOR:
        if mode == "cadrage" and phase != "cadrage":
            raise ValueError("the Director frames before the Build phase only")
        if mode == "interpretation":
            if phase != "interpret":
                raise ValueError("the interpretation follows an approved Verifier (LR-07)")
            if state["interpreted"]:
                raise ValueError("the cross interpretation runs once (LR-07)")
    if dead:
        return _dead(state, key, reason or "dead agent", agent, iteration, agent in EXPERTS)
    state["failures"][key] = 0
    log = {"iteration": iteration, "verdict": "DONE", "produced": 0}
    if agent == BUILDER:
        state["phase"] = "verify"
        return {"action": "verify", "iteration": iteration}, log
    if agent == DIRECTOR and mode == "interpretation":
        state["interpreted"] = True
        state["status"] = "success"
        return {"action": "done", "iteration": 0}, log
    if agent != VERIFIER:
        return {"action": "continue", "agent": agent, "iteration": 0, "uncollected": list(state["uncollected"])}, log
    assert parsed is not None
    log["verdict"] = parsed["verdict"]
    log["produced"] = len(parsed["issues"])
    state["issues"] = parsed["issues"]
    if (parsed["verdict"] == "APPROVED" and parsed["tests_passed"] and parsed["protocol_followed"]
            and parsed["rerun_consistent"]):
        state["phase"] = "interpret"
        return {"action": "success", "iteration": iteration, "interpret": True}, log
    if counters.cap_reached(iteration, state["max_iterations"]):
        state["status"] = "failed"
        return {"action": "fail", "iteration": iteration, "issues": parsed["issues"],
                "journal_entry": "experiment invalidated",
                "reason": "%d iterations without approval: explicit failure" % iteration}, log
    state["iteration"] = iteration + 1
    state["phase"] = "build"
    return {"action": "fix", "iteration": iteration + 1, "tests_passed": parsed["tests_passed"],
            "protocol_followed": parsed["protocol_followed"], "rerun_consistent": parsed["rerun_consistent"],
            "issues": parsed["issues"]}, log
